package br.com.onda;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import android.animation.ValueAnimator;import android.graphics.*;import android.os.*;import java.io.*;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class TouchMotionTest {
 final Instrumentation ins=getInstrumentation();final Context c=ins.getTargetContext();Activity activity;Probe button;boolean hadMotion,oldMotion;String oldTheme,oldScale;int clicks;boolean batteryChanged,oldSaving;
 static class Probe extends TouchButton{int draws;Probe(Context c){super(c);}@Override protected void onDraw(Canvas canvas){draws++;super.onDraw(canvas);}}
 String shell(String command)throws Exception{try(ParcelFileDescriptor p=ins.getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){return new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).trim();}}
 void scale(String value)throws Exception{shell("settings put global animator_duration_scale "+value);long end=System.currentTimeMillis()+4000;while(System.currentTimeMillis()<end&&ValueAnimator.areAnimatorsEnabled()!=!value.equals("0"))Thread.sleep(40);assertEquals(!value.equals("0"),ValueAnimator.areAnimatorsEnabled());}
 @Before public void before()throws Exception{SharedPreferences p=c.getSharedPreferences("appearance",0);hadMotion=p.contains(TouchMotion.KEY);oldMotion=p.getBoolean(TouchMotion.KEY,true);oldTheme=p.getString("theme",null);oldScale=shell("settings get global animator_duration_scale");p.edit().putBoolean(TouchMotion.KEY,true).commit();scale("1");activity=ins.startActivitySync(new Intent(c,AppearanceActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.waitForIdleSync();ins.runOnMainSync(()->{AppearanceStyles.choose(activity,AppearancePalette.find("festival"));button=new Probe(activity);button.setStateListAnimator(null);button.setText("Toque para testar");button.setTextSize(16);button.setMinHeight(Ui.dp(c,48));Ui.primary(button);button.setOnClickListener(v->clicks++);FrameLayout root=activity.findViewById(android.R.id.content);root.addView(button,new FrameLayout.LayoutParams(Ui.dp(c,200),Ui.dp(c,56),Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL));});long end=System.currentTimeMillis()+4000;while(System.currentTimeMillis()<end&&!activity.hasWindowFocus())Thread.sleep(50);ins.waitForIdleSync();assertTrue(activity.hasWindowFocus());}
 @After public void after()throws Exception{if(batteryChanged){shell("cmd power set-mode "+(oldSaving?"1":"0"));shell("dumpsys battery reset");}if(activity!=null)ins.runOnMainSync(()->{if(button!=null)button.stopMotion();activity.finish();});SharedPreferences.Editor e=c.getSharedPreferences("appearance",0).edit();if(hadMotion)e.putBoolean(TouchMotion.KEY,oldMotion);else e.remove(TouchMotion.KEY);if(oldTheme==null)e.remove("theme");else e.putString("theme",oldTheme);e.commit();Ui.install(AppearancePalette.find(oldTheme));if(oldScale!=null&&oldScale.matches("[0-9.]+"))shell("settings put global animator_duration_scale "+oldScale);else shell("settings delete global animator_duration_scale");}
 void press(boolean down){ins.runOnMainSync(()->button.setPressed(down));}
 void idleScale()throws Exception{Thread.sleep(220);ins.runOnMainSync(()->{assertEquals(1f,button.getScaleX(),.001f);assertEquals(1f,button.getScaleY(),.001f);assertFalse(button.motionRunning());});}
 void report(String key,JSONObject item)throws Exception{File file=new File(c.getFilesDir(),"touch-motion-tests.json");JSONObject root=file.exists()?new JSONObject(new String(java.nio.file.Files.readAllBytes(file.toPath()),java.nio.charset.StandardCharsets.UTF_8)):new JSONObject();root.put(key,item);java.nio.file.Files.write(file.toPath(),root.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 @Test public void realTouchFinishesAndIdleHasNoDrawLoop()throws Exception{long time=SystemClock.uptimeMillis();ins.runOnMainSync(()->{MotionEvent event=MotionEvent.obtain(time,time,MotionEvent.ACTION_DOWN,button.getWidth()/2f,button.getHeight()/2f,0);button.dispatchTouchEvent(event);event.recycle();});Thread.sleep(150);ins.runOnMainSync(()->{assertEquals(.97f,button.getScaleX(),.005f);assertFalse(button.motionRunning());});Bitmap picture=ins.getUiAutomation().takeScreenshot();if(picture!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"color-touch-preview.png"))){picture.compress(Bitmap.CompressFormat.PNG,100,out);}finally{picture.recycle();}ins.runOnMainSync(()->{MotionEvent event=MotionEvent.obtain(time,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,button.getWidth()/2f,button.getHeight()/2f,0);button.dispatchTouchEvent(event);event.recycle();});ins.waitForIdleSync();idleScale();assertEquals(1,clicks);Thread.sleep(450);assertEquals(View.LAYER_TYPE_NONE,button.getLayerType());int[] draws={0};ins.runOnMainSync(()->draws[0]=button.draws);Thread.sleep(750);ins.runOnMainSync(()->{assertEquals(draws[0],button.draws);assertFalse(button.motionRunning());});report("touch",new JSONObject().put("actualClickCount",clicks).put("pressedScale",.97).put("restingScale",1).put("idleDrawsOver750ms",0).put("noPermanentLayer",button.getLayerType()==View.LAYER_TYPE_NONE));}
 @Test public void preferenceSystemAndBatteryGatesDisableMotion()throws Exception{assertFalse(TouchMotion.allowed(true,true,true,true,true));assertFalse(TouchMotion.allowed(true,false,false,true,true));assertFalse(TouchMotion.allowed(true,false,true,false,true));assertFalse(TouchMotion.allowed(true,false,true,true,false));assertTrue(TouchMotion.allowed(true,false,true,true,true));android.os.PowerManager power=(android.os.PowerManager)c.getSystemService(Context.POWER_SERVICE);oldSaving=power.isPowerSaveMode();shell("dumpsys battery unplug");batteryChanged=true;shell("cmd power set-mode 1");long end=System.currentTimeMillis()+5000;while(System.currentTimeMillis()<end&&!power.isPowerSaveMode())Thread.sleep(50);assertTrue("Battery saver was not enabled",power.isPowerSaveMode());press(true);idleScale();press(false);shell("cmd power set-mode 0");end=System.currentTimeMillis()+5000;while(System.currentTimeMillis()<end&&power.isPowerSaveMode())Thread.sleep(50);assertFalse(power.isPowerSaveMode());c.getSharedPreferences("appearance",0).edit().putBoolean(TouchMotion.KEY,false).commit();press(true);idleScale();press(false);c.getSharedPreferences("appearance",0).edit().putBoolean(TouchMotion.KEY,true).commit();scale("0");press(true);idleScale();press(false);report("gates",new JSONObject().put("userDisabled",true).put("androidAnimationsDisabled",true).put("actualBatterySaverDisabledMotion",true).put("hiddenAndDisabledPolicy",true));}
 @Test public void cancellingHidingAndPreferenceReopeningPreserveNativeButtons()throws Exception{press(true);Thread.sleep(110);ins.runOnMainSync(()->button.setEnabled(false));idleScale();ins.runOnMainSync(()->button.setEnabled(true));press(false);press(true);ins.runOnMainSync(()->((ViewGroup)button.getParent()).removeView(button));idleScale();Switch[] motion={null};ins.runOnMainSync(()->{motion[0]=(Switch)find(activity.findViewById(android.R.id.content),"Animar botões ao tocar");assertNotNull(motion[0]);motion[0].setChecked(false);activity.finish();});activity=ins.startActivitySync(new Intent(c,AppearanceActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.waitForIdleSync();ins.runOnMainSync(()->assertFalse(((Switch)find(activity.findViewById(android.R.id.content),"Animar botões ao tocar")).isChecked()));report("lifecycle",new JSONObject().put("disabledReset",true).put("detachReset",true).put("preferenceSaved",true));}
 View find(View v,String label){if(label.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View found=find(g.getChildAt(i),label);if(found!=null)return found;}}return null;}
}
